    assert.notEqual(play.phase, "wheek");
    assert.notEqual(play.phase, "bask");
    assert.notEqual(play.phase, "circle");
    assert.notEqual(play.phase, "perch-talk");
    assert.notEqual(play.phase, "scent");
    assert.notEqual(play.phase, "bow");
