  assert.match(readFileSync(join(root, "src/lib/pets/garden.ts"), "utf8"), /key: "oak"[\s\S]{0,80}slug: "mast"/);
  const target = P.pickTarget([WIN], 80, "oak", WORK, 176);
  assert.ok(target);
